def solve(g):
    R,C=len(g),len(g[0])
    out=[row[:] for row in g]
    seeds=[(r,c) for r in range(R) for c in range(C) if g[r][c]==3]
    for r,c in seeds:
        for dr,row in enumerate([[5,5,5,5,5],[2,0,5,0,2],[2,0,3,0,2],[2,0,0,0,2]]):
            rr=r-2+dr
            if 0<=rr<R:
                for dc in range(-2,3):
                    cc=c+dc
                    if 0<=cc<C and row[dc+2]!=0: out[rr][cc]=row[dc+2]
        rr=r+2
        if 0<=rr<R:
            for cc in range(C):
                out[rr][cc]=8 if abs(cc-c)<=2 else 2
    return out
g=[[0]*19 for _ in range(17)]
for r,c in [(3,4),(8,11),(13,6)]: g[r][c]=3
out=solve(g)
for row in out: print(row)
